'use strict';
const fs=require('fs'),path=require('path');
const all=[];
function r(act,s,sec,t,d,ch,cat,kw){
  all.push({act,act_short:s,section:String(sec),section_title:t,
    section_desc:d,chapter:String(ch),chapter_title:'',category:cat,
    keywords:Array.isArray(kw)?kw:kw.split(' ')});
}

// IEA 1872 — ALL sections 1-167 comprehensive
const ieaData=[
  ["1","Short title, extent and commencement","The Indian Evidence Act, 1872 extends to the whole of India except the State of Jammu and Kashmir. It came into force on 1 September 1872. It applies to all judicial proceedings in or before any court, including courts martial other than courts martial convened under the Army Act and Indian Navy Discipline Act.","1","Evidence Law",["IEA S1 short title 1872 India courts judicial proceedings army navy 1 September"]],
  ["2","Repeal of enactments","This section repealed various earlier Acts. Historical significance only.","1","Evidence Law",["IEA S2 repeal enactments historical"]],
  ["3","Definitions — Fact, Relevant, Evidence, Proved, Disproved","'Fact' means anything perceptible by senses or any mental condition of which person is conscious. 'Relevant' — one fact connected with another in ways mentioned in S.5-55. 'Evidence' — oral statements by witnesses; documents including electronic records produced for court inspection. 'Proved' — court believes it to exist beyond reasonable doubt (criminal) or more probable than not (civil). 'Disproved' — court believes fact does not exist.","1","Evidence Law",["IEA S3 definitions fact relevant evidence proved disproved oral documentary electronic reasonable doubt more probable"]],
  ["4","May presume, Shall presume, Conclusive proof","'May presume' — court may either regard fact as proved or may require proof. 'Shall presume' — court shall regard fact as proved unless disproved. 'Conclusive proof' — when one fact declared conclusive proof of another, no evidence to disprove allowed. Example: S.112 — birth during marriage is conclusive proof of legitimacy.","1","Evidence Law",["IEA S4 may presume shall presume conclusive proof court fact disproved S112 legitimacy"]],
  ["5","Evidence may be given of facts in issue and relevant facts","Evidence may be given in any suit or proceeding of the existence or non-existence of every fact in issue, and of such other facts as are hereinafter declared to be relevant, and of no others.","2","Evidence Law",["IEA S5 evidence facts in issue relevant declared only admissible"]],
  ["6","Res gestae","Facts which, though not in issue, are so connected with a fact in issue as to form part of the same transaction, are relevant. The connection must be of such a nature that the facts form part of the same transaction. Spontaneous exclamations during/immediately after event are admissible.","2","Evidence Law",["IEA S6 res gestae same transaction spontaneous exclamation connected form part time place"]],
  ["7","Facts which are occasions, causes or effects","Facts which are the occasion, cause, or effect, immediate or otherwise, of relevant facts or facts in issue, or which constitute the state of things under which they happened, or which afforded an opportunity for their occurrence, are relevant.","2","Evidence Law",["IEA S7 occasion cause effect state things opportunity relevant facts"]],
  ["8","Motive, preparation, previous or subsequent conduct","Any fact is relevant which shows or constitutes a motive or preparation for any fact in issue or relevant fact; and the conduct of any party or person in reference to such matter is relevant.","2","Evidence Law",["IEA S8 motive preparation conduct party relevant previous subsequent"]],
  ["9","Facts necessary to explain or introduce","Facts necessary to explain or introduce a fact in issue or relevant fact, or which support or rebut an inference suggested by such fact, or which establish identity of any thing or person, or fix the time or place — relevant in so far as necessary.","2","Evidence Law",["IEA S9 explain introduce identity time place fix support rebut inference necessary"]],
  ["10","Things said or done by conspirator in reference to common design","Where there is reasonable ground to believe that two or more persons have conspired, anything said, done or written by any one of such persons in reference to their common intention, after the time when such intention was first entertained by any one of them, is a relevant fact.","2","Evidence Law",["IEA S10 conspiracy conspirator common design said done written reasonable ground"]],
  ["11","When facts not otherwise relevant become relevant","Facts not otherwise relevant are relevant if: inconsistent with any fact in issue or relevant fact; or if by themselves or in connection with other facts they make existence or non-existence of any fact in issue highly probable or improbable.","2","Evidence Law",["IEA S11 inconsistent highly probable improbable otherwise irrelevant relevant facts"]],
  ["12","In suits for damages, facts tending to enable court to determine amount","In suits in which damages are claimed, any fact which will enable the court to determine the amount of damages which ought to be awarded, is relevant.","2","Evidence Law",["IEA S12 damages amount court determine fact relevant suit"]],
  ["13","Facts relevant when right or custom is in question","Where the question is as to the existence of any right or custom, the following facts are relevant: any transaction by which right or custom was created, claimed, modified, recognised, asserted, or denied; particular instances in which right or custom was claimed, recognised, or exercised.","2","Evidence Law",["IEA S13 right custom transaction created claimed instances recognised exercised disputed"]],
  ["14","Facts showing state of mind or body","Facts showing the existence of any state of mind — intention, knowledge, good faith, negligence, rashness, ill-will, good-will towards any person — or showing existence of any state of body or bodily feeling — are relevant when such state is in issue or relevant.","2","Evidence Law",["IEA S14 state of mind intention knowledge good faith negligence rashness body feeling relevant"]],
  ["15","Facts bearing on question whether act was accidental or intentional","When there is a question whether an act was accidental or intentional, the fact that such act formed part of a series of similar occurrences in each of which the person was concerned, is relevant. Doctrine of similar facts — shows guilty knowledge or intention.","2","Evidence Law",["IEA S15 accidental intentional series similar acts guilty knowledge intent doctrine"]],
  ["16","Existence of course of business when relevant","When there is a question whether a particular act was done, the existence of any course of business, according to which it naturally would have been done, is a relevant fact. Example: letter posted per routine office procedure — presumed received.","2","Evidence Law",["IEA S16 course of business routine procedure letter posted presumed received relevant"]],
  ["17","Admission defined","An admission is a statement, oral or documentary or contained in electronic form, which suggests any inference as to any fact in issue or relevant fact, and which is made by any of the persons mentioned in sections 18-20.","3","Evidence Law",["IEA S17 admission defined statement oral documentary electronic inference fact issue relevant"]],
  ["18","Admission by party to proceeding or agent","Statements by: party to proceeding; agent authorised by party; person in representative character (executor, administrator, trustee); person with proprietary or pecuniary interest in subject of proceeding; person who has any fiduciary duty.","3","Evidence Law",["IEA S18 admission party agent authorised representative executor administrator trustee interest fiduciary"]],
  ["19","Admissions by persons whose position must be proved","Statements made by a person whose position or liability it is necessary to prove as against any party to the suit are admissions if made while occupying that position.","3","Evidence Law",["IEA S19 admissions person position liability necessary prove against party"]],
  ["20","Admissions by persons expressly referred to","Statements made by persons to whom a party to the suit has expressly referred for information in reference to a matter in dispute are admissions against such party.","3","Evidence Law",["IEA S20 admissions person expressly referred information matter dispute against party"]],
  ["21","Proof of admissions against persons making them","Admissions may be proved against the person who makes them or his representative in interest but not by him. A party cannot use his own admission as evidence in his favour.","3","Evidence Law",["IEA S21 proof admissions against person making not own favour representative"]],
  ["23","Admissions in civil cases protected if without prejudice","In civil cases, no admission is relevant if made upon express condition that evidence of it is not to be given, or under circumstances from which parties agreed evidence should not be given. Without prejudice communications protected.","3","Evidence Law",["IEA S23 admissions civil without prejudice express condition not given protected"]],
  ["24","Confession by inducement, threat or promise — irrelevant","A confession made by accused is irrelevant if caused by inducement, threat or promise from person in authority, sufficient to give grounds for supposing that by making it accused would gain advantage or avoid evil. Protection against coerced confessions.","3","Evidence Law",["IEA S24 confession irrelevant inducement threat promise person in authority advantage evil coerced"]],
  ["25","Confession to police officer — not proved","No confession made to a police officer shall be proved as against a person accused. Absolute bar. Even voluntary confession to police is inadmissible. Purpose: prevent torture.","3","Evidence Law",["IEA S25 confession police officer not proved absolute bar voluntary inadmissible torture"]],
  ["26","Confession by accused while in custody of police","No confession made by any person whilst in custody of police officer, unless made in immediate presence of Magistrate, shall be proved as against such person.","3","Evidence Law",["IEA S26 confession police custody Magistrate presence proved admissible"]],
  ["27","How much of information received from accused may be proved — discovery","If any fact is discovered in consequence of information received from accused in police custody, so much of such information as relates distinctly to the fact discovered may be proved. Exception to S.25 and S.26.","3","Evidence Law",["IEA S27 discovery fact accused information police custody distinctly related proved exception S25 S26"]],
  ["28","Confession made after removal of impression","If impression caused by inducement/threat/promise has been fully removed, a subsequent confession is not excluded under S.24.","3","Evidence Law",["IEA S28 confession after removal impression S24 subsequent admissible"]],
  ["29","Confession otherwise relevant — not excluded due to caution etc.","A confession is not excluded if made: upon a promise of secrecy; in consequence of deception; when the person was drunk; in answer to questions he need not have answered; because of form of questions.","3","Evidence Law",["IEA S29 confession not excluded secrecy deception drunk questions need not have answered"]],
  ["30","Co-accused confession","When more persons than one are being tried jointly for the same offence, and a confession made by one of such persons affecting himself and some other of such persons is proved, the court may take into consideration such confession as against such other person. Not substantive evidence — only taken into consideration.","3","Evidence Law",["IEA S30 co-accused confession jointly tried affecting himself other court take into consideration not substantive"]],
  ["31","Admissions not conclusive but may estop","Admissions are not conclusive proof. They may, however, operate as estoppels under subsequent sections. An admission shifts the burden of proof.","3","Evidence Law",["IEA S31 admissions not conclusive may estop shifts burden of proof"]],
  ["32","Statements by persons who are dead etc.","A statement of a person who is dead, cannot be found, incapable of giving evidence, or whose attendance cannot be procured without unreasonable delay — is relevant fact in eight circumstances: statement made in course of business; against interest; as to cause of death (dying declaration); as to public right/custom; others.","3","Evidence Law",["IEA S32 dead person statement eight circumstances dying declaration course of business against interest public right"]],
  ["33","Relevancy of evidence given in former proceeding","Evidence given by witness in judicial proceeding is relevant for proving truth of facts it states in subsequent proceeding when witness is: dead; cannot be found; incapable of giving evidence; kept out of way by adverse party.","3","Evidence Law",["IEA S33 former proceeding evidence relevant witness dead not found incapable kept out way subsequent"]],
  ["34","Entries in books of account — regularly kept","Entries in books of account regularly kept in course of business are relevant when they refer to matter court has to inquire into. But not alone sufficient to charge person with liability — corroboration needed.","4","Evidence Law",["IEA S34 books of account regularly kept business relevant charge liability not alone corroboration"]],
  ["35","Relevancy of entry in public record made in performance of duty","Entry in any public or official book, register or electronic record stating fact in issue or relevant fact, made by public servant in discharge of official duty, is itself a relevant fact.","4","Evidence Law",["IEA S35 public record entry official duty register electronic fact relevant public servant"]],
  ["36","Relevancy of statements in maps, charts and plans","Statements of facts in issue or relevant facts, made in published maps or charts generally offered for sale or made under authority of Central or State Government, are themselves relevant facts.","4","Evidence Law",["IEA S36 maps charts plans published sale government authority facts relevant"]],
  ["37","Relevancy of statement as to fact of public nature contained in Acts","When the court has to form opinion as to existence of any fact of a public nature, any statement of it in a public Act of Parliament of the United Kingdom, India or any State is a relevant fact.","4","Evidence Law",["IEA S37 Act Parliament public nature statement relevant fact"]],
  ["38","Relevancy of statements as to any law contained in certain books","When the court has to form an opinion as to a law of any country, any statement of such law contained in a book published in the country, and purporting to be written by a person having special means of knowing such law, is relevant.","4","Evidence Law",["IEA S38 foreign law book published specialist means knowing relevant court form opinion"]],
  ["39","What evidence to be given when statement forms part of conversation","When statement is part of longer statement or conversation or document, evidence shall be given of so much and no more as is necessary for full understanding of the nature and effect of the statement.","4","Evidence Law",["IEA S39 statement part conversation document full understanding context so much no more"]],
  ["40","Previous judgments relevant to bar second suit or trial","Existence of judgment which by law prevents court from taking cognizance is relevant when question is whether court should take cognizance. Res judicata.","5","Evidence Law",["IEA S40 previous judgment relevant bar second suit trial cognizance res judicata"]],
  ["41","Relevancy of certain judgments in probate etc.","A final judgment, order or decree of a competent court, in the exercise of probate, matrimonial, admiralty, or insolvency jurisdiction, which confers or takes away a legal character, or which declares any person to be entitled to any such character, is conclusive proof of that character.","5","Evidence Law",["IEA S41 probate matrimonial admiralty insolvency judgment conclusive proof legal character entitlement"]],
  ["42","Relevancy and effect of judgments, orders or decrees other than those mentioned in S.40 and 41","Judgments, orders or decrees other than those in S.40 and S.41 are relevant if they relate to matters of public nature relevant to the enquiry; but such judgments, orders or decrees are not conclusive proof of that which they state.","5","Evidence Law",["IEA S42 judgments orders decrees S40 S41 otherwise public nature relevant not conclusive"]],
  ["43","Judgments in cases not binding — irrelevant","Judgments other than those in S.40, S.41, S.42 are irrelevant unless the existence of such judgment is itself a fact in issue or is relevant under some other provision of this Act.","5","Evidence Law",["IEA S43 irrelevant judgment not in S40 S41 S42 unless fact in issue otherwise relevant"]],
  ["44","Fraud or collusion in obtaining judgment, or incompetency of court, may be proved","Any party to a suit or other proceeding may show that any judgment, order or decree which is relevant under S.40, S.41 or S.42, and which has been proved by the adverse party, was delivered by a court not competent to deliver it, or was obtained by fraud or collusion.","5","Evidence Law",["IEA S44 fraud collusion obtaining judgment incompetent court show prove adverse party"]],
  ["45","Opinions of experts","When the court has to form an opinion upon a point of foreign law, science, art, identity of handwriting or finger impressions, the opinions of persons specially skilled in such foreign law, science, art or in such questions, are relevant facts. Court is not bound by expert opinion.","5","Evidence Law",["IEA S45 expert opinion foreign law science art handwriting fingerprint specially skilled relevant not bound"]],
  ["46","Facts bearing upon opinions of experts","Facts, not otherwise relevant, are relevant if they support or are inconsistent with the opinions of experts, when such opinions are relevant.","5","Evidence Law",["IEA S46 facts bearing expert opinion support inconsistent relevant"]],
  ["47","Opinion as to handwriting when relevant","When the court has to form an opinion as to the person by whom any document was written or signed, the opinion of any person acquainted with the handwriting of the person by whom it is supposed to be written or signed that it was or was not written or signed by that person, is a relevant fact.","5","Evidence Law",["IEA S47 handwriting opinion acquainted person wrote signed relevant fact court"]],
  ["48","Opinion as to existence of right or custom when relevant","When the court has to form an opinion as to the existence of any general custom or right, the opinions, as to the existence of such custom or right, of persons who would be likely to know of its existence if it existed, are relevant.","5","Evidence Law",["IEA S48 general custom right opinion likely know existence relevant court"]],
  ["49","Opinion as to usages, tenets etc.","Opinion of persons with special means of knowledge as to usages, tenets of any body of men, constitution of religious or charitable foundation, or meaning of words in particular districts, is relevant.","5","Evidence Law",["IEA S49 usages tenets religious charitable constitution meaning words specialist knowledge relevant"]],
  ["50","Opinion on relationship when relevant","When court has to form opinion as to relationship of one person to another, opinion of any person who has special means of knowledge on the subject, expressed by conduct, is relevant.","5","Evidence Law",["IEA S50 opinion relationship special means knowledge conduct relevant family"]],
  ["51","Grounds of opinion relevant","Whenever opinion of living person is relevant, the grounds on which that opinion is based are also relevant.","5","Evidence Law",["IEA S51 grounds opinion relevant living person based"]],
  ["52","In civil cases, character of person irrelevant — general rule","In civil cases, fact that character of any person is such as to render probable or improbable any conduct imputed to him is irrelevant, except in so far as such character appears from facts otherwise relevant.","5","Evidence Law",["IEA S52 character civil cases irrelevant general rule imputed conduct improbable"]],
  ["53","In criminal cases, previous good character relevant","In criminal proceedings, fact that accused is of good character is relevant. Prosecution cannot lead bad character evidence unless accused first puts good character in issue.","5","Evidence Law",["IEA S53 criminal good character accused relevant prosecution rebuttal bad character issue"]],
  ["54","Previous bad character not relevant except in reply","In criminal cases, bad character of accused is irrelevant unless evidence of good character has first been given, in which case it becomes relevant.","5","Evidence Law",["IEA S54 bad character irrelevant unless good character given first reply rebuttal"]],
  ["55","Character as affecting damages","In civil cases in which damages are claimed, the fact that the conduct of any party was influenced by his good or bad character is relevant.","5","Evidence Law",["IEA S55 character damages civil cases conduct influenced good bad relevant"]],
  ["56","Fact judicially noticeable need not be proved","No fact need be proved of which court will take judicial notice — all laws in force in India, public Acts Parliament, course of proceedings Parliament, seals of courts, public holidays, geography, commencement of judicial year.","6","Evidence Law",["IEA S56 judicial notice need not prove laws Acts Parliament seals courts holidays geography"]],
  ["57","Facts of which court must take judicial notice","Court shall take judicial notice of: laws in force in India; course of Parliament proceedings; existence title and national flag of every State; marks of jurisdiction; division of time.","6","Evidence Law",["IEA S57 must take judicial notice laws Parliament proceedings title flag State time division"]],
  ["58","Facts admitted need not be proved","No fact need be proved at trial if parties agree to admit it at or before hearing in writing.","6","Evidence Law",["IEA S58 admitted facts need not prove parties agree hearing writing"]],
  ["59","Oral evidence — all facts except documents","All facts except the contents of documents or electronic records may be proved by oral evidence.","7","Evidence Law",["IEA S59 oral evidence all facts except documents electronic records contents"]],
  ["60","Oral evidence must be direct","Oral evidence must be direct: what was seen — by person who saw; what was heard — by person who heard; what was perceived by senses — by person who perceived; opinion — by person holding it. Hearsay rule.","7","Evidence Law",["IEA S60 oral evidence direct eyewitness hearsay rule saw heard perceived opinion"]],
  ["61","Proof of contents of documents — primary or secondary","Contents of documents may be proved by primary evidence or by secondary evidence.","8","Evidence Law",["IEA S61 proof contents documents primary secondary evidence"]],
  ["62","Primary evidence","The document itself produced for inspection of court. If document executed in several parts, each part is primary evidence. Electronic records stored in computer: original is primary evidence.","8","Evidence Law",["IEA S62 primary evidence original document inspection court parts electronic"]],
  ["63","Secondary evidence — types","Secondary evidence includes: certified copies; copies made by mechanical processes; copies made from original; counterparts; oral accounts of contents by persons who have seen document.","8","Evidence Law",["IEA S63 secondary evidence types certified mechanical counterpart oral account"]],
  ["64","Primary evidence preferred","Contents of documents must be proved by primary evidence as the general rule.","8","Evidence Law",["IEA S64 primary evidence preferred general rule contents documents"]],
  ["65","When secondary evidence is admissible","Secondary evidence admissible: original with adverse party who does not produce it; original lost; original cannot be physically produced; original is public document; original consists of numerous accounts.","8","Evidence Law",["IEA S65 secondary evidence admissible original adverse party lost public document numerous accounts"]],
  ["66","Rules as to notice to produce","Before giving secondary evidence, notice to produce must be served on party who has original. If original not produced after notice: secondary evidence admissible.","8","Evidence Law",["IEA S66 notice produce secondary evidence original party not produced admissible"]],
  ["67","Proof of signature and handwriting of person","If document alleged to be signed by person, that person's signature or handwriting must be proved to be his.","8","Evidence Law",["IEA S67 signature handwriting proof person alleged written signed"]],
  ["68","Proof of execution of document required to be attested","If law requires attestation, document cannot be used as evidence until one attesting witness at least has been called to prove execution.","8","Evidence Law",["IEA S68 attested document proof execution one witness called prove"]],
  ["69","Proof where no attesting witness found","If no attesting witness found, must prove that attestation of at least one attesting witness is in his handwriting and subscription of executant is in his handwriting.","8","Evidence Law",["IEA S69 no attesting witness handwriting attestation subscription executant proved"]],
  ["70","Admission of execution by party to attested document","Admission by party to attested document of its execution by himself is sufficient proof of its execution as against him.","8","Evidence Law",["IEA S70 admission execution attested document party sufficient against him"]],
  ["71","Proof when attesting witness denies execution","If attesting witness denies execution, it may be proved by other evidence.","8","Evidence Law",["IEA S71 attesting witness denies execution other evidence"]],
  ["72","Proof of document not required to be attested","Unattested document which law does not require to be attested may be proved by any secondary evidence of its contents.","8","Evidence Law",["IEA S72 unattested document secondary evidence not required attested law"]],
  ["73","Comparison of signature, writing or seal with one admitted or proved","In order to ascertain whether a signature, writing, or seal is that of the person by whom it purports to have been written or made, any signature, writing, or seal admitted or proved to the satisfaction of the court to have been written or made by that person may be compared by the court.","8","Evidence Law",["IEA S73 comparison signature writing seal admitted proved court identify person"]],
  ["74","Public documents","Documents forming the acts or records of: sovereign authority; official bodies and tribunals; public officers — legislative, judicial, executive — of any part of India, Commonwealth, or foreign country. Published official documents; maps made by government authority.","9","Evidence Law",["IEA S74 public documents sovereign authority official bodies legislative judicial executive India Commonwealth foreign"]],
  ["75","Private documents","All other documents are private documents.","9","Evidence Law",["IEA S75 private documents all others not public"]],
  ["76","Certified copies of public documents","Every public officer having custody of public document shall give certified copy on demand and payment. Certificate: true copy of document, signed, sealed, dated by officer with name and official title.","9","Evidence Law",["IEA S76 certified copies public document officer custody demand payment certificate signed sealed"]],
  ["77","Proof of documents by production of certified copies","Such certified copies may be produced in proof of the contents of the public documents or parts of the public documents of which they purport to be copies.","9","Evidence Law",["IEA S77 certified copies proof contents public document produced"]],
  ["78","Proof of other official documents","Public Acts Parliament: by Gazette or certified copy. Acts State Legislature: by same. Proceedings of Parliament/Legislature: by journals or minutes or books under authority. Proclamations, orders, regulations: by Official Gazette. By-laws, rules: by copy signed/sealed by authority.","9","Evidence Law",["IEA S78 official documents Parliament State acts journals minutes Gazette proclamations rules by-laws"]],
  ["79","Presumption as to genuineness of certified copies","Court shall presume genuine every document purporting to be a certificate, certified copy or other document, duly certified by officer of Central or State Government.","10","Evidence Law",["IEA S79 presumption genuineness certified copies Central State Government officer document court"]],
  ["80","Presumption as to documents produced as record of evidence","Documents purporting to be records of evidence given in judicial proceedings: court presumes genuine, in accordance with law, duly taken.","10","Evidence Law",["IEA S80 presumption record evidence judicial proceedings genuine accordance law duly"]],
  ["81","Presumption as to Gazettes, newspapers, Acts","Court presumes genuineness of: London Gazette, Official Gazette, State Government Gazette, newspapers/journals, private Acts of Parliament UK.","10","Evidence Law",["IEA S81 presumption Gazette newspaper London Official State Act Parliament genuine"]],
  ["82","Presumption as to document admissible under British Act","Court presumes document admissible under any Act of Parliament of UK and which purports to be signed by any judge, magistrate, or official, was duly signed.","10","Evidence Law",["IEA S82 presumption British Act signed judge magistrate official duly"]],
  ["83","Presumption as to maps and plans","Court presumes maps or plans made by authority of Central or State Government were so made and are accurate. Maps made for purposes of any cause must be proved accurate.","10","Evidence Law",["IEA S83 presumption maps plans Central State Government accurate cause prove"]],
  ["84","Presumption as to collection of laws and reports of decisions","Court presumes genuineness of book purporting to be printed/published under authority of government of any country containing its laws, and of books purporting to contain reports of court decisions.","10","Evidence Law",["IEA S84 presumption laws book printed published government authority reports court decisions"]],
  ["85","Presumption as to powers of attorney","Court shall presume that every document purporting to be a power of attorney, executed before and authenticated by notary public or court or Judge or Magistrate or Indian Consul, was so executed and authenticated.","10","Evidence Law",["IEA S85 presumption power of attorney notary public court Judge Magistrate Indian Consul executed authenticated"]],
  ["86","Presumption as to certified copies of foreign judicial records","Court may presume certified copy of foreign judicial record is genuine and accurate if certified in manner usual in that country.","10","Evidence Law",["IEA S86 certified copy foreign judicial record genuine accurate usual manner court"]],
  ["87","Presumption as to books, maps and charts","Court may presume book/map/chart was written by person and at time/place purported to be.","10","Evidence Law",["IEA S87 books maps charts written person time place purported presumption"]],
  ["88","Presumption as to telegraphic messages","Court may presume message forwarded from telegraph office corresponds with message delivered for transmission. But no presumption as to person who delivered it.","10","Evidence Law",["IEA S88 telegraphic message forwarded corresponds delivered transmission no presumption person"]],
  ["89","Presumption as to due execution etc. of documents not produced","Where document called for and not produced: presumed to have been attested, stamped and executed as required by law.","10","Evidence Law",["IEA S89 presumption due execution document not produced attested stamped required law"]],
  ["90","Presumption as to documents 30 years old","Document purporting or proved to be 30 years old, produced from proper custody: court may presume that signature and every other part in handwriting of person purported, and if executed or attested, duly executed and attested.","10","Evidence Law",["IEA S90 30 years document proper custody presume signature handwriting duly executed attested"]],
  ["91","Evidence of terms of contracts etc. reduced to document form — Parol evidence rule","When terms of contract or grant or disposition of property reduced to documentary form, no evidence shall be given to prove the terms except the document itself or secondary evidence of it.","11","Evidence Law",["IEA S91 parol evidence rule contract grant disposition document only secondary evidence terms no oral"]],
  ["92","Exclusion of evidence of oral agreement","When terms proved as per S.91, no oral agreement evidence admissible to contradict, vary, add to or subtract from terms. Exceptions: collateral agreements; existence of custom; agreement not yet in operation; invalidating circumstances; parol evidence admissible.","11","Evidence Law",["IEA S92 oral agreement excluded contradict vary add subtract terms exceptions collateral custom invalidating"]],
  ["93","Exclusion of evidence to explain or amend ambiguous document","Evidence of facts which would show meaning of ambiguous document cannot be given. Patent ambiguity: no extrinsic evidence. Latent ambiguity (S.96): extrinsic evidence allowed.","11","Evidence Law",["IEA S93 exclude evidence explain ambiguous document patent ambiguity S96 latent extrinsic evidence"]],
  ["94","Exclusion of evidence against application of document to existing facts","When language of document is plain and applies accurately to existing facts, evidence of any intention inconsistent with its plain meaning shall not be admitted.","11","Evidence Law",["IEA S94 exclude evidence inconsistent plain meaning document applies accurately existing facts"]],
  ["95","Evidence as to document meaningless in reference to existing facts","When language of document is meaningless in reference to existing facts, evidence may be given to show what was meant.","11","Evidence Law",["IEA S95 document meaningless reference existing facts evidence show meaning"]],
  ["96","Evidence as to application of language which can apply to one only of several persons","When language used in document applies equally well to each of two or more persons, evidence may be given to show which of those persons was intended.","11","Evidence Law",["IEA S96 application language two persons evidence which intended latent ambiguity"]],
  ["97","Evidence as to application of language to one of two sets of facts","When the language of a document applies partly to each of two or more sets of existing facts, but the whole of it does not apply correctly to either, evidence may be given to show to which of such sets of facts it was meant to apply.","11","Evidence Law",["IEA S97 language partly two sets facts evidence which meant apply"]],
  ["98","Evidence as to meaning of illegible characters etc.","Evidence may be given to show the meaning of illegible or not commonly intelligible characters, foreign, obsolete, technical, local and provincial expressions, abbreviations and words used in a peculiar sense.","11","Evidence Law",["IEA S98 illegible characters foreign obsolete technical local provincial abbreviations peculiar sense evidence meaning"]],
  ["99","Who may give evidence of agreement varying terms of document","Persons who are not parties to a document, or their representatives in interest, may give evidence of any facts tending to show a contemporaneous agreement varying the terms of the document.","11","Evidence Law",["IEA S99 third parties evidence agreement varying terms document contemporaneous"]],
  ["101","Burden of proof — general","Whoever desires court to give judgment as to any legal right or liability dependent on existence of facts, must prove that those facts exist. Burden of proof lies on that person.","12","Evidence Law",["IEA S101 burden of proof legal right liability facts exist prove general rule"]],
  ["102","On whom burden of proof lies","The burden of proof in a suit or proceeding lies on that person who would fail if no evidence at all were given on either side.","12","Evidence Law",["IEA S102 burden of proof fails no evidence either side proceeding suit"]],
  ["103","Burden of proof as to particular fact","Burden of proof as to any particular fact lies on that person who wishes court to believe in its existence, unless law provides that proof shall lie on any particular person.","12","Evidence Law",["IEA S103 burden particular fact person wishes believe existence unless law provides"]],
  ["104","Burden of proving fact to make evidence admissible","The burden of proving any fact necessary to make evidence admissible is on the person who wishes to give the evidence.","12","Evidence Law",["IEA S104 burden proving fact necessary make evidence admissible person wishes give"]],
  ["105","Burden of proving exception in criminal cases","When a person is accused of any offence, the burden of proving existence of circumstances bringing case within any general exception in IPC is upon him.","12","Evidence Law",["IEA S105 burden proving exception criminal IPC general exception accused on accused balance probabilities"]],
  ["106","Burden of proving fact especially within knowledge","When any fact is especially within knowledge of any person, burden of proving that fact is upon him.","12","Evidence Law",["IEA S106 burden fact especially within knowledge person prove"]],
  ["107","Burden of proving death of person known to have been alive within 30 years","When question is whether man is alive or dead, and shown to have been alive within 30 years, burden of proving he is dead is on person who affirms it.","12","Evidence Law",["IEA S107 burden proving death alive within 30 years person affirms"]],
  ["108","Burden of proving that person is alive who has not been heard of for 7 years","When question is whether man is alive or dead, and shown not to have been heard of for 7 years by those who would naturally have heard of him, burden of proving he is alive is on person affirming it.","12","Evidence Law",["IEA S108 burden proving alive 7 years not heard naturally heard person affirming"]],
  ["109","Burden of proof as to relationship in certain cases","When question is whether persons are partners, landlord and tenant, or principal and agent, and shown to have been acting as such, burden of proving they do not stand in such relationship is on person who affirms it.","12","Evidence Law",["IEA S109 burden proof relationship partner landlord tenant principal agent acting ceased affirm"]],
  ["110","Burden of proof as to ownership","When question is whether person is owner of anything of which he is shown to be in possession, burden of proving he is not the owner is on person who affirms that he is not the owner.","12","Evidence Law",["IEA S110 burden ownership possession person affirms not owner prove"]],
  ["111","Proof of good faith in transactions where one party is in relation of active confidence","Where there is question as to good faith of transaction between parties, one of whom stands to the other in a position of active confidence, burden of proving good faith of transaction is on party who is in a position of active confidence.","12","Evidence Law",["IEA S111 good faith active confidence burden proving transaction position"]],
  ["111A","Presumption as to certain offences — abetment of mutiny etc.","In a prosecution for the offences of waging war, abetting mutiny etc., the court may presume the commission of the offence.","12","Evidence Law",["IEA S111A presumption prosecution waging war mutiny offence court may presume"]],
  ["112","Birth during marriage conclusive proof of legitimacy","The fact that any person was born during continuance of a valid marriage between his mother and any man, or within 280 days after its dissolution, the mother remaining unmarried, shall be conclusive proof that he is the legitimate son of that man, unless parties had no access to each other at any time when he could have been begotten.","12","Evidence Law",["IEA S112 birth during marriage conclusive proof legitimacy 280 days mother no access exception"]],
  ["113","Proof of cession of territory","When there is question of cession of territory by India, the fact of such cession and the terms of cession shall be deemed to have been duly established if the facts have been officially stated and the statement has been duly published.","12","Evidence Law",["IEA S113 cession territory India officially stated duly published established"]],
  ["113A","Presumption as to abetment of suicide by married woman","When question is whether husband or relative abetted suicide of woman within 7 years of marriage after cruelty, court may presume such abetment.","12","Evidence Law",["IEA S113A presumption abetment suicide married woman seven years marriage cruelty may presume"]],
  ["113B","Presumption as to dowry death","When shown that woman suffered cruelty/harassment for dowry soon before her death, court shall presume her husband or relative caused dowry death.","12","Evidence Law",["IEA S113B dowry death shall presume cruelty harassment soon before husband relative mandatory"]],
  ["114","Court may presume existence of certain facts","Court may presume existence of any fact which it thinks likely to have happened, regard being had to common course of natural events, human conduct, public and private business. Illustrations include: mail delivered; judicial acts done properly; accomplice unworthy of credit unless corroborated.","12","Evidence Law",["IEA S114 court may presume existence fact common course natural events human conduct illustrations mail judicial"]],
  ["114A","Presumption as to absence of consent in rape prosecutions","In prosecution for rape under clauses of S.376(2), where sexual intercourse by accused proved and woman states she did not consent, court shall presume no consent.","12","Evidence Law",["IEA S114A presumption no consent rape prosecution S376(2) woman states shall presume"]],
  ["115","Estoppel","When one person has, by his declaration, act or omission, intentionally caused or permitted another person to believe a thing to be true and to act upon such belief, neither he nor his representative shall be allowed to deny the truth of that thing.","12","Evidence Law",["IEA S115 estoppel declaration act omission caused permitted believe true act upon cannot deny"]],
  ["116","Estoppel of tenant","No tenant of immoveable property, or person claiming through such tenant, shall, during the continuance of the tenancy, be permitted to deny that the landlord of such tenant had, at the beginning of the tenancy, a title to such immoveable property.","12","Evidence Law",["IEA S116 estoppel tenant landlord title beginning tenancy cannot deny immoveable"]],
  ["117","Estoppel of acceptor of bill of exchange, bailee or licensee","No acceptor of a bill of exchange shall be permitted to deny that the drawer had authority to draw such bill or to endorse it. No bailee or licensee shall be permitted to deny that his bailor or licensor had, at the time when the bailment or licence commenced, authority to make such bailment or grant such licence.","12","Evidence Law",["IEA S117 estoppel acceptor bill drawer authority bailee licensor bailor authority bailment licence"]],
  ["118","Who may testify — competency","All persons shall be competent to testify unless court considers they are prevented from understanding questions put to them or from giving rational answers by tender years, extreme old age, disease, or any other cause.","13","Evidence Law",["IEA S118 competency witness all persons unless prevent understanding rational answers years age disease"]],
  ["119","Dumb witness","Witness unable to speak may give evidence by writing, signs or other intelligible means in open court, which shall be deemed to be oral evidence.","13","Evidence Law",["IEA S119 dumb witness speak writing signs intelligible open court oral evidence"]],
  ["120","Parties to civil suit and spouses — competency","In civil proceedings, parties and their spouses are competent witnesses. In criminal proceedings, accused is competent witness for defence; husband and wife competent but not compellable.","13","Evidence Law",["IEA S120 parties civil suit spouses competency criminal accused defence husband wife not compellable"]],
  ["121","Judges and Magistrates — privilege","No Judge or Magistrate shall be compelled to answer any question as to his own conduct in court in his official capacity, or as to anything which came to his knowledge in court in his official capacity.","13","Evidence Law",["IEA S121 judge magistrate privilege not compelled answer conduct official capacity knowledge"]],
  ["122","Communications during marriage — privilege","No person shall be compelled to disclose any communication made during marriage by spouse. Marital privilege.","13","Evidence Law",["IEA S122 marital privilege communication during marriage spouse not compelled disclose"]],
  ["123","Evidence as to affairs of State — privilege","No one shall be permitted to give any evidence derived from unpublished official records relating to any affairs of State, except with permission of the officer at the head of the department concerned.","13","Evidence Law",["IEA S123 affairs of State privilege unpublished official records department head permission"]],
  ["124","Official communications — privilege","No public officer shall be compelled to disclose communications made to him in official confidence, when he considers that public interests would suffer by disclosure.","13","Evidence Law",["IEA S124 official communications privilege public officer official confidence public interest"]],
  ["125","Information as to commission of offences — privilege","No Magistrate or police officer shall be compelled to say whence he got any information as to commission of any offence. No revenue officer compelled to say whence he got information about revenue offences.","13","Evidence Law",["IEA S125 police Magistrate information commission offence source privilege not compelled revenue"]],
  ["126","Professional communications — legal professional privilege","No advocate shall be permitted, unless with client's express consent, to disclose any communication made to him in course and for purpose of his employment, or to state contents of any document he has become acquainted with in course of professional employment, or to disclose advice given to client.","13","Evidence Law",["IEA S126 legal professional privilege advocate client communication employment confidential advice document express consent"]],
  ["127","Section 126 to apply to interpreters etc.","The provisions of section 126 shall apply to interpreters, and the clerks or servants of barristers, pleaders, attorneys and vakils.","13","Evidence Law",["IEA S127 S126 applies interpreters clerks servants barristers pleaders attorneys vakils"]],
  ["128","Privilege not waived by volunteering evidence","If any party to a suit gives evidence in such suit, he shall not be deemed to have consented to disclosure under section 126.","13","Evidence Law",["IEA S128 privilege not waived volunteering evidence party suit S126 not consented"]],
  ["129","Confidential communications with legal advisers","No one shall be compelled to disclose to the court any confidential communication which has taken place between him and his legal professional adviser, unless he offers himself as a witness.","13","Evidence Law",["IEA S129 confidential legal adviser communication compelled disclose court unless volunteer witness"]],
  ["130","Production of title deeds of witness not a party","No witness who is not a party to a suit shall be compelled to produce his title deeds to any property, or any document by virtue of which he holds any property as pledgee or mortgagee.","13","Evidence Law",["IEA S130 title deeds witness not party not compelled produce property pledgee mortgagee"]],
  ["131","Production of documents or electronic records which another person could refuse to produce","No one shall be compelled to produce documents in his possession, which any other person would be entitled to refuse to produce if they were in his possession, unless such last-mentioned person consents to their production.","13","Evidence Law",["IEA S131 production documents electronic records another person refuse possession unless consent"]],
  ["132","Witness not excused from answering on ground that answer will criminate him","Witness shall not be excused from answering on ground that answer will criminate him. But such answer shall not subject him to arrest or prosecution for any offence which it discloses except perjury.","13","Evidence Law",["IEA S132 not excused answering criminate except perjury no prosecution arrest answer"]],
  ["133","Accomplice — competent witness","An accomplice shall be a competent witness against an accused person. Conviction is not illegal merely because it proceeds upon uncorroborated testimony of an accomplice. But practice: corroboration desirable.","13","Evidence Law",["IEA S133 accomplice competent witness conviction not illegal uncorroborated testimony corroboration desirable"]],
  ["134","Number of witnesses — no minimum","No particular number of witnesses shall in any case be required for proof of any fact.","13","Evidence Law",["IEA S134 number witnesses no minimum required proof fact any case"]],
  ["135","Order of production and examination","Order in which witnesses produced and examined shall be regulated by law and practice relating to civil and criminal procedure respectively, or in absence of such law by discretion of court.","13","Evidence Law",["IEA S135 order production examination witnesses civil criminal procedure law practice discretion"]],
  ["136","Judge to decide admissibility","When party proposes to give evidence of fact, judge may ask in what manner it would be relevant; and shall admit if relevant, not otherwise.","14","Evidence Law",["IEA S136 judge decide admissibility relevant fact admit or not manner evidence"]],
  ["137","Examination in chief, cross-examination, re-examination","Examination of witness by party calling him: examination in chief. By adverse party: cross-examination. Subsequent examination by calling party: re-examination.","14","Evidence Law",["IEA S137 examination in chief cross-examination re-examination calling adverse party subsequent"]],
  ["138","Order of examinations and cross-examination","Witnesses first examined in chief, then cross-examined if adverse party so desires, then re-examined. Cross-examination need not be confined to facts in examination in chief.","14","Evidence Law",["IEA S138 order examinations cross-examination not confined examination in chief adverse party"]],
  ["139","Cross-examination of person called to produce document","Person summoned to produce document does not become a witness merely by producing it. Cannot be cross-examined unless actually called as witness.","14","Evidence Law",["IEA S139 produce document not witness cross-examination unless called witness"]],
  ["140","Witnesses to character","Witnesses to character may be cross-examined and re-examined.","14","Evidence Law",["IEA S140 character witnesses cross-examined re-examined"]],
  ["141","Leading questions defined","A question suggesting the answer which the person putting it wishes or expects to receive is called a leading question.","14","Evidence Law",["IEA S141 leading question defined suggests answer expects wishes"]],
  ["142","When leading questions not to be asked in examination in chief","Leading questions must not be asked in examination in chief or re-examination except: with permission of court; to matters not in dispute; and in other exceptional circumstances.","14","Evidence Law",["IEA S142 leading questions not examination in chief re-examination except permission court not in dispute"]],
  ["143","Leading questions may be asked in cross-examination","Leading questions may be asked in cross-examination.","14","Evidence Law",["IEA S143 leading questions cross-examination may be asked"]],
  ["144","Evidence as to matters in writing","Any witness may be questioned as to previous statements made by him in writing or reduced to writing, and relevant to matters in question, by the rules of evidence.","14","Evidence Law",["IEA S144 previous statements writing witness questioned matters relevant"]],
  ["145","Cross-examination as to previous statements in writing","Witness may be cross-examined as to previous statements in writing or reduced to writing without such writing being shown first; but if intended to contradict by writing, his attention must first be called to those parts.","14","Evidence Law",["IEA S145 cross-examination previous statements writing show attention called contradict"]],
  ["146","Questions lawful in cross-examination","Witness may be asked questions which: test his veracity; discover who he is and his position in life; shake his credit by injuring his character. These are limited by S.148-155.","14","Evidence Law",["IEA S146 questions cross-examination lawful veracity position shake credit character injured limited S148-155"]],
  ["147","When witness to be compelled to answer","If any such question as referred to in S.146 relates to a fact in issue or relevant fact, the witness is bound to answer it.","14","Evidence Law",["IEA S147 compelled answer fact in issue relevant fact cross-examination"]],
  ["148","Court to decide when question shall be asked","If question relates to matter not relevant except to affect credit by injuring character, court decides whether witness shall be compelled to answer. Factors: how strongly it bears upon veracity, remoteness, witness asked to impute criminal act to himself.","14","Evidence Law",["IEA S148 court decide compel answer credit injuring character remoteness veracity criminal act"]],
  ["149","Question not to be asked without reasonable grounds","No such question as referred to in S.148 ought to be asked unless person asking it has reasonable grounds for thinking the imputation conveyed is well-founded.","14","Evidence Law",["IEA S149 reasonable grounds question character imputation well-founded S148"]],
  ["150","Procedure of court in case of question asked without reasonable grounds","If the court finds that a question is asked without reasonable grounds for asking it, it may, if the question relates to criminal matter, report the circumstances of the case to the High Court.","14","Evidence Law",["IEA S150 court report High Court question without reasonable grounds criminal matter"]],
  ["151","Indecent and scandalous questions","The court may forbid any questions or inquiries which it regards as indecent or scandalous, although such questions may have some bearing on the questions before the court.","14","Evidence Law",["IEA S151 indecent scandalous questions court forbid bearing questions before court"]],
  ["152","Questions intended to insult or annoy","The court shall forbid any question which appears to it to be intended to insult or annoy, or which, though proper in form, appears to the court needlessly offensive in character.","14","Evidence Law",["IEA S152 questions insult annoy court forbid needlessly offensive character"]],
  ["153","Exclusion of evidence to contradict answers to questions testing veracity","When witness has answered question relevant only to shake his credit by injuring his character, no evidence shall be given to contradict him. But if he answers falsely, he may be charged with giving false evidence.","14","Evidence Law",["IEA S153 exclude evidence contradict answers veracity credit character falsely charged perjury"]],
  ["154","Court may permit leading questions to own witness — hostile witness","The court may, in its discretion, permit the person who calls a witness to put any questions to him which might be put in cross-examination by the adverse party.","14","Evidence Law",["IEA S154 hostile witness leading questions court permission own witness cross-examination adverse party"]],
  ["155","Impeaching credit of witness","Credit of witness may be impeached: by evidence of persons testifying him unworthy of credit; by proof witness bribed; by proof of former statements inconsistent with present evidence; (in rape case woman's character not relevant unless court allows).","14","Evidence Law",["IEA S155 impeach credit witness bribed inconsistent former statements unworthy rape character not relevant"]],
  ["156","Questions not to be asked without reasonable grounds — credit","No question falling within S.155 ought to be asked unless person asking it has reasonable grounds.","14","Evidence Law",["IEA S156 reasonable grounds questions credit witness S155"]],
  ["157","Former statements may be used to corroborate","In order to corroborate testimony of witness, any former statement made by such witness relating to same fact, at or about the time when fact took place, or before any authority legally competent to investigate, may be proved.","14","Evidence Law",["IEA S157 corroboration former statement witness same fact time authority investigate"]],
  ["158","What matters may be proved in connection with proved statement under S.32 or S.33","Whenever any statement relevant under S.32 or S.33 is proved, all matters may be proved to contradict, corroborate, impeach, or confirm credit of person who made it.","14","Evidence Law",["IEA S158 statement S32 S33 proved contradict corroborate impeach confirm credit"]],
  ["159","Refreshing memory","Witness may refresh memory by referring to writing made by himself at time of transaction, or so soon afterwards that court considers transaction was then fresh in memory.","14","Evidence Law",["IEA S159 refresh memory writing transaction time fresh memory witness"]],
  ["160","Testimony to facts stated in document mentioned in S.159","Witness may testify to facts mentioned in document used to refresh memory, although he has no specific recollection of the facts themselves, if he is sure they were correctly recorded.","14","Evidence Law",["IEA S160 testimony facts document S159 refresh memory no recollection correctly recorded sure"]],
  ["161","Right of adverse party as to writing used to refresh memory","Any writing referred to under S.159 must be produced and shown to adverse party if required; such party may cross-examine witness thereupon.","14","Evidence Law",["IEA S161 adverse party writing refresh memory produced shown cross-examine S159"]],
  ["162","Production of documents","Witness summoned to produce document shall, if in his possession or power, bring it to court. Validity of objection to production decided by court.","14","Evidence Law",["IEA S162 produce document witness possession power bring court objection validity"]],
  ["163","Giving as evidence, document called for and produced on notice","When party calls for and inspects a document, he is bound to give it as evidence if adverse party requires it.","14","Evidence Law",["IEA S163 document called produced notice inspected bound give evidence adverse party requires"]],
  ["164","Using as evidence of document production of which was refused on notice","When party refuses to produce a document which he was required to produce, he cannot afterwards use the document as evidence without the consent of the other party or the order of the court.","14","Evidence Law",["IEA S164 refused produce document cannot use evidence without consent court order"]],
  ["165","Power of judge to put questions","Judge may ask any question in any form at any time of any witness or party about any fact relevant or irrelevant and may order production of any document or thing. Parties have no right to re-examine questions put by judge.","14","Evidence Law",["IEA S165 judge power questions any form time relevant irrelevant order production document no re-examine"]],
  ["166","Power of jury or assessors to put questions","In trials by jury, the jury or assessors may put questions to witnesses through or by leave of the judge, which the judge himself might put and which he considers proper.","14","Evidence Law",["IEA S166 jury assessors questions witnesses through leave judge proper"]],
  ["167","No new trial for improper admission or rejection of evidence","The improper admission or rejection of evidence shall not be a ground of itself for a new trial or reversal of any decision in any case, if it appears to the court before which such objection is raised that, independently of the evidence objected to and admitted, there was sufficient evidence to justify the decision.","15","Evidence Law",["IEA S167 improper admission rejection evidence not ground new trial sufficient evidence justify decision"]],
];
ieaData.forEach(([sec,t,d,ch,cat,kw])=>r("Indian Evidence Act, 1872","IEA",sec,t,d,ch,cat,kw));


